// 此源门仅核预约事实前人物来源；不冒真实Talk/完整Family或World执行验收。
#include "resident/domains/interaction/appointments/personal_appointment_presence.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
int main(){try{
 auto check=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"provider"};CommonState seed;seed.identity.tick=5;seed.next_instance_id=40;
 ActorRecord provider;provider.id="provider";provider.alive=true;seed.actors.insert(provider.id,provider);ActorRecord actor;actor.id="actor:2";actor.created_tick=2;actor.alive=true;seed.actors.insert(actor.id,actor);seed.facts.insert(actor.id,{actor.id,"actor_creation","family_birth"});
 const StableId accepted="personal_appointment_accepted:4",cancelled="personal_appointment_cancelled:6",started="personal_appointment_started:8",finished="personal_appointment_finished:10";seed.facts.insert(accepted,{accepted,personal_appointment_accepted_kind,personal_appointment_module});CommonStore common(seed,catalog);PersonalAppointmentState state;PersonalAppointmentAccepted a;a.fact_id=accepted;a.policy_id="visit";a.contact.actor_id=actor.id;a.contact.provider_actor_id=provider.id;a.contact.tick=2;state.accepted.insert(accepted,a);
 FamilyDeathOriginRead none=[](const StableId&)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,std::nullopt,{}};};auto valid=[&](const FamilyDeathOriginRead& read){return validate_personal_appointment_presence(common,*catalog,state,read);};check(valid(none).ok,"dynamic actor created before actual acceptance, no birthday required");auto original=common.state();common.state().facts.erase(actor.id);common.state().facts.insert(actor.id,{actor.id,"actor_creation","family_birth"});check(!valid(none).ok,"same-tick creation moved after accepted source must reject");common.state()=original;common.state().actors.find(actor.id)->created_tick=3;check(!valid(none).ok,"future created_tick cannot backfill earlier promise");common.state()=original;
 common.state().actors.find(actor.id)->alive=false;common.state().facts.insert("military:5",{"military:5","military_casualties","military"});FamilyDeathOriginRead death=[&](const StableId& id)->Outcome<std::optional<FamilyDeathOrigin>>{return id==actor.id?Outcome<std::optional<FamilyDeathOrigin>>{true,FamilyDeathOrigin{id,"military:5","battle",2},{}}:Outcome<std::optional<FamilyDeathOrigin>>{true,std::nullopt,{}};};check(valid(death).ok,"later same-tick real death does not erase valid acceptance");check(!valid(none).ok,"current dead without actual source is unavailable");
 PersonalAppointmentCancelled c;c.fact_id=cancelled;c.appointment_id=accepted;c.contact=a.contact;state.cancelled.insert(cancelled,c);common.state().facts.insert(cancelled,{cancelled,personal_appointment_cancelled_kind,personal_appointment_module});check(!valid(death).ok,"after-casualty cancellation cannot use delayed Family registration gap");state.cancelled.erase(cancelled);common.state().facts.erase(cancelled);
 PersonalAppointmentStarted s;s.fact_id=started;s.appointment_id=accepted;s.contact=a.contact;s.action_id="action:7";state.started.insert(started,s);common.state().facts.insert(started,{started,personal_appointment_started_kind,personal_appointment_module});check(!valid(death).ok,"after-casualty start cannot revive participant");common.state().facts.erase("military:5");common.state().facts.insert("military:5",{"military:5","military_casualties","military"});check(valid(death).ok,"start genuinely preceding later same-tick casualty remains valid");
 PersonalAppointmentFinished f;f.fact_id=finished;f.appointment_id=accepted;f.start_fact_id=started;f.action_id=s.action_id;f.tick=3;f.success=true;state.finished.insert(finished,f);common.state().facts.insert(finished,{finished,personal_appointment_finished_kind,personal_appointment_module});check(!valid(death).ok,"success after real death forbidden");state.finished.find(finished)->success=false;state.finished.find(finished)->reason="PersonalAppointmentParticipantUnavailable";check(valid(death).ok,"original interrupted action preserves valid living start");std::cout<<"APPOINTMENT_PRESENCE source checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
